// Package dist renders the package-manager metadata published with every
// release: the Homebrew formula (homebrew-tap) and the Scoop manifest
// (scoop-bucket). Both are generated from the release's checksums.txt, so the
// URLs and SHA-256 hashes always match the uploaded archives.
package dist

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"regexp"
	"strings"
	"text/template"
)

// Description is the one-line summary shown by `brew info` / `scoop info`.
const Description = "Terminal UI for managing Docker on remote hosts over TCP or SSH"

// DefaultRepo is the GitHub repository the release archives are published to.
const DefaultRepo = "kirg0/d9c"

// Checksums maps a release file name to its lowercase hex SHA-256.
type Checksums map[string]string

var sha256Re = regexp.MustCompile(`^[0-9a-f]{64}$`)

// ParseChecksums reads sha256sum output ("<hash>  <name>", optionally with the
// "*" binary-mode marker before the name). Blank lines are skipped; a malformed
// line or hash is an error.
func ParseChecksums(r io.Reader) (Checksums, error) {
	sums := Checksums{}
	sc := bufio.NewScanner(r)
	for n := 1; sc.Scan(); n++ {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) != 2 {
			return nil, fmt.Errorf("checksums line %d: want \"<sha256>  <file>\", got %q", n, line)
		}
		hash := strings.ToLower(fields[0])
		if !sha256Re.MatchString(hash) {
			return nil, fmt.Errorf("checksums line %d: invalid sha256 %q", n, fields[0])
		}
		sums[strings.TrimPrefix(fields[1], "*")] = hash
	}
	if err := sc.Err(); err != nil {
		return nil, fmt.Errorf("read checksums: %w", err)
	}
	if len(sums) == 0 {
		return nil, errors.New("checksums file is empty")
	}
	return sums, nil
}

// StageName is the archive's base name and its single top-level directory,
// e.g. "d9c_v1.2.3_linux_amd64" (matches release.yml).
func StageName(version, goos, goarch string) string {
	return fmt.Sprintf("d9c_v%s_%s_%s", version, goos, goarch)
}

// ArchiveName is the release asset for a platform: .zip on Windows, .tar.gz
// elsewhere.
func ArchiveName(version, goos, goarch string) string {
	ext := ".tar.gz"
	if goos == "windows" {
		ext = ".zip"
	}
	return StageName(version, goos, goarch) + ext
}

// Release describes one published version.
type Release struct {
	Version string // SemVer without the leading "v"
	Repo    string // "owner/name"; empty means DefaultRepo
	Sums    Checksums
}

func (r Release) repo() string {
	if r.Repo == "" {
		return DefaultRepo
	}
	return r.Repo
}

// Homepage is the project page on GitHub.
func (r Release) Homepage() string {
	return "https://github.com/" + r.repo()
}

// DownloadURL is the asset URL for a platform archive.
func (r Release) DownloadURL(goos, goarch string) string {
	return fmt.Sprintf("%s/releases/download/v%s/%s",
		r.Homepage(), r.Version, ArchiveName(r.Version, goos, goarch))
}

// asset is one platform archive with its verified hash.
type asset struct {
	URL, SHA256, Dir string
}

// asset resolves a platform archive; a missing checksum is an error when
// required, otherwise it yields ok=false so optional platforms are skipped.
func (r Release) asset(goos, goarch string, required bool) (a asset, ok bool, err error) {
	name := ArchiveName(r.Version, goos, goarch)
	sum, found := r.Sums[name]
	if !found {
		if required {
			return asset{}, false, fmt.Errorf("no checksum for %s", name)
		}
		return asset{}, false, nil
	}
	return asset{URL: r.DownloadURL(goos, goarch), SHA256: sum, Dir: StageName(r.Version, goos, goarch)}, true, nil
}

func (r Release) validate() error {
	if !semverRe.MatchString(r.Version) {
		return fmt.Errorf("version %q is not MAJOR.MINOR.PATCH (without a leading v)", r.Version)
	}
	return nil
}

var semverRe = regexp.MustCompile(`^\d+\.\d+\.\d+$`)

var formulaTmpl = template.Must(template.New("formula").Parse(`# typed: false
# frozen_string_literal: true

# Generated by the d9c release workflow (cmd/distgen) — do not edit by hand.
class D9c < Formula
  desc "{{.Desc}}"
  homepage "{{.Homepage}}"
  version "{{.Version}}"
  license "MIT"

  on_macos do
    on_intel do
      url "{{.DarwinAMD64.URL}}"
      sha256 "{{.DarwinAMD64.SHA256}}"
    end
    on_arm do
      url "{{.DarwinARM64.URL}}"
      sha256 "{{.DarwinARM64.SHA256}}"
    end
  end

  on_linux do
    on_intel do
      url "{{.LinuxAMD64.URL}}"
      sha256 "{{.LinuxAMD64.SHA256}}"
    end
    on_arm do
      url "{{.LinuxARM64.URL}}"
      sha256 "{{.LinuxARM64.SHA256}}"
    end
  end

  def install
    bin.install "d9c"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/d9c -version")
  end
end
`))

// HomebrewFormula renders Formula/d9c.rb for the tap. All four macOS/Linux
// archives (amd64 + arm64) must be present in the checksums.
func (r Release) HomebrewFormula() (string, error) {
	if err := r.validate(); err != nil {
		return "", err
	}
	data := struct {
		Desc, Homepage, Version string

		DarwinAMD64, DarwinARM64, LinuxAMD64, LinuxARM64 asset
	}{Desc: Description, Homepage: r.Homepage(), Version: r.Version}
	for _, p := range []struct {
		goos, goarch string
		dst          *asset
	}{
		{"darwin", "amd64", &data.DarwinAMD64},
		{"darwin", "arm64", &data.DarwinARM64},
		{"linux", "amd64", &data.LinuxAMD64},
		{"linux", "arm64", &data.LinuxARM64},
	} {
		a, _, err := r.asset(p.goos, p.goarch, true)
		if err != nil {
			return "", err
		}
		*p.dst = a
	}
	var buf bytes.Buffer
	if err := formulaTmpl.Execute(&buf, data); err != nil {
		return "", fmt.Errorf("render formula: %w", err)
	}
	return buf.String(), nil
}

// scoopArch is one entry of a Scoop manifest's "architecture" map.
type scoopArch struct {
	URL        string `json:"url"`
	Hash       string `json:"hash,omitempty"`
	ExtractDir string `json:"extract_dir"`
}

type scoopArchMap struct {
	AMD64 *scoopArch `json:"64bit,omitempty"`
	ARM64 *scoopArch `json:"arm64,omitempty"`
}

type scoopHash struct {
	URL string `json:"url"`
}

type scoopAutoupdate struct {
	Architecture scoopArchMap `json:"architecture"`
	Hash         scoopHash    `json:"hash"`
}

// scoopManifest keeps the field order Scoop's own manifests use.
type scoopManifest struct {
	Version      string          `json:"version"`
	Description  string          `json:"description"`
	Homepage     string          `json:"homepage"`
	License      string          `json:"license"`
	Architecture scoopArchMap    `json:"architecture"`
	Bin          string          `json:"bin"`
	Checkver     string          `json:"checkver"`
	Autoupdate   scoopAutoupdate `json:"autoupdate"`
}

// ScoopManifest renders bucket/d9c.json. windows/amd64 is required; the
// windows/arm64 build is included when its checksum is present. The
// autoupdate block lets `scoop` / Excavator bump the manifest on its own.
func (r Release) ScoopManifest() ([]byte, error) {
	if err := r.validate(); err != nil {
		return nil, err
	}
	m := scoopManifest{
		Version:     r.Version,
		Description: Description,
		Homepage:    r.Homepage(),
		License:     "MIT",
		Bin:         "d9c.exe",
		Checkver:    "github",
		Autoupdate: scoopAutoupdate{
			Hash: scoopHash{URL: "$baseurl/checksums.txt"},
		},
	}
	// $version placeholders are substituted by Scoop on autoupdate.
	tmpl := Release{Version: "$version", Repo: r.Repo}
	for _, p := range []struct {
		goarch   string
		required bool
		dst, upd **scoopArch
	}{
		{"amd64", true, &m.Architecture.AMD64, &m.Autoupdate.Architecture.AMD64},
		{"arm64", false, &m.Architecture.ARM64, &m.Autoupdate.Architecture.ARM64},
	} {
		a, ok, err := r.asset("windows", p.goarch, p.required)
		if err != nil {
			return nil, err
		}
		if !ok {
			continue
		}
		*p.dst = &scoopArch{URL: a.URL, Hash: a.SHA256, ExtractDir: a.Dir}
		*p.upd = &scoopArch{
			URL:        tmpl.DownloadURL("windows", p.goarch),
			ExtractDir: StageName("$version", "windows", p.goarch),
		}
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "    ")
	if err := enc.Encode(m); err != nil {
		return nil, fmt.Errorf("encode scoop manifest: %w", err)
	}
	return buf.Bytes(), nil
}
